func msPatch(bitmap *port.Bitmap, lines *port.Cells, line int32, width int32, height int32, pixels *port.Cells) int32 {
	var w int32 = port.BitmapW(bitmap)
	var h int32 = port.BitmapH(bitmap)
	var x0 int32 = evidence.LnGet(lines, line, evidence.LhX0())
	var y0 int32 = evidence.LnGet(lines, line, evidence.LhY0())
	var dx int32 = evidence.LnGet(lines, line, evidence.LhX1()) - x0
	var dy int32 = evidence.LnGet(lines, line, evidence.LhY1()) - y0
	var channels int32 = port.BitmapChannels(bitmap)
	var u int32 = 0
	var v int32 = 0
	var x int32 = 0
	var y int32 = 0
	for v < 12 {
		y = msPixel(y0+(((v-2)*dy)/8), h, height)
		u = 0
		for u < 32 {
			x = msPixel(x0+((((u*2)+1)*dx)/64), w, width)
			port.CellsPush(pixels, msGrey(bitmap, x, y, channels))
			u += 1
		}
		v += 1
	}
	return 0
}

func MsNcc(pixels *port.Cells, a int32, b int32, count int32) int32 {
	// Scaled integer Pearson correlation. Require positive covariance and reject near-flat crops.
	var i int32 = 0
	var x int32 = 0
	var y int32 = 0
	var sx int64 = int64(0)
	var sy int64 = int64(0)
	var xx int64 = int64(0)
	var yy int64 = int64(0)
	var xy int64 = int64(0)
	var vx int64 = int64(0)
	var vy int64 = int64(0)
	var covariance int64 = int64(0)
	for i < count {
		x = port.CellsAt(pixels, a+i)
		y = port.CellsAt(pixels, b+i)
		sx += int64(x)
		sy += int64(y)
		xx += int64(x * x)
		yy += int64(y * y)
		xy += int64(x * y)
		i += 1
	}
	vx = ((int64(count) * xx) - (sx * sx)) / int64(count)
	vy = ((int64(count) * yy) - (sy * sy)) / int64(count)
	covariance = ((int64(count) * xy) - (sx * sy)) / int64(count)
	if (covariance > int64(0)) && (vx > int64(count)) && (vy > int64(count)) {
		if ((covariance * covariance) * int64(100)) >= ((vx * vy) * int64(81)) {
			return 1
		}
	}
	return 0
}

func msEdgeAdd(fl *port.Cells, edge *port.Cells, line int32, bottom int32) int32 {
	// Insert from the physical edge inward. Bound the band even on very long pages.
	var y int32 = msY(fl, line)
	var i int32 = 0
	var j int32 = port.CellsLen(edge)
	var side int32 = 0
	for i < j {
		side = y - msY(fl, port.CellsAt(edge, i))
		if bottom == 0 {
			side = 0 - side
		}
		if side > 0 {
			j = i
		} else {
			i += 1
		}
	}
	if i >= msBand() {
		return 0
	}
	j = port.CellsLen(edge) - 1
	if port.CellsLen(edge) < msBand() {
		port.CellsPush(edge, 0)
		j += 1
	}
	for j > i {
		port.CellsSet(edge, j, port.CellsAt(edge, j-1))
		j -= 1
	}
	port.CellsSet(edge, i, line)
	return 0
}

func MsSample(bitmap *port.Bitmap, lines *port.Cells, first int32, width int32, height int32, offsets *port.Cells, pixels *port.Cells, top *port.Cells, bottom *port.Cells) int32 {
	// The page unit may release its bitmap after this call. Retain only fixed-size edge-line samples.
	if (width <= 0) || (height <= 0) || (port.BitmapW(bitmap) <= 0) || (port.BitmapH(bitmap) <= 0) || (port.CellsLen(pixels) > 4000000) {
		return 0
	}
	port.CellsDrop(top, 0)
	port.CellsDrop(bottom, 0)
	var i int32 = first
	var line int32 = 0
	var j int32 = 0
	for port.CellsLen(offsets) < evidence.LnCount(lines) {
		port.CellsPush(offsets, -1)
	}
	for i < evidence.LnCount(lines) {
		if evidence.LnGet(lines, i, evidence.LhCount()) > 0 {
			msEdgeAdd(lines, top, i, 0)
			msEdgeAdd(lines, bottom, i, 1)
		}
		i += 1
	}
	for j < (port.CellsLen(top) + port.CellsLen(bottom)) {
		if j < port.CellsLen(top) {
			line = port.CellsAt(top, j)
		} else {
			line = port.CellsAt(bottom, j-port.CellsLen(top))
		}
		if port.CellsAt(offsets, line) < 0 {
			port.CellsSet(offsets, line, port.CellsLen(pixels))
			msPatch(bitmap, lines, line, width, height, pixels)
		}
		j += 1
	}
	return 0
}

